# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs):
    acc = 0
    out = []
    for v in xs[:-1]:
        acc = acc + v
        out.append(acc)
    return out

# region: sift
def sift(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: render
def render(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(shape(render(sift(fold(gather(raw))))))

